import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]

    limit = max(a)
    spf = list(range(limit + 1))
    for i in range(2, int(limit ** 0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, limit + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # For each prime, record its exponent in every A_i.
    exponents = {}
    m = n - 1
    for i, value in enumerate(a):
        x = value
        while x > 1:
            p = spf[x]
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            exponents.setdefault(p, [0] * m)[i] = e

    answer = 1
    for p, edge_exp in exponents.items():
        max_height = sum(edge_exp)
        powers = [1] * (max_height + 1)
        for k in range(1, max_height + 1):
            powers[k] = powers[k - 1] * p % MOD

        # dp[h] sums the scores accumulated so far for normalized walks
        # whose current height above their minimum is h.
        dp = [1]  # The first sequence element has exponent zero.
        width = 0
        for i, e in enumerate(edge_exp):
            next_dp = [0] * (width + e + 1)
            prior_count = i + 1
            for height, value in enumerate(dp):
                if value == 0:
                    continue
                if e == 0:
                    # There is only one allocation for this prime on this edge.
                    next_dp[height] = (next_dp[height] + value * powers[height]) % MOD
                else:
                    # Choose the sign that raises the walk.
                    raised = height + e
                    next_dp[raised] = (next_dp[raised] + value * powers[raised]) % MOD

                    # Choose the sign that lowers the walk.
                    if height >= e:
                        lowered = height - e
                        next_dp[lowered] = (next_dp[lowered] + value * powers[lowered]) % MOD
                    else:
                        # The minimum decreases. All prior vertices are shifted up.
                        shift = e - height
                        factor = pow(p, shift * prior_count, MOD)
                        next_dp[0] = (next_dp[0] + value * factor) % MOD
            dp = next_dp
            width += e

        answer = answer * (sum(dp) % MOD) % MOD

    print(answer)

if __name__ == '__main__':
    main()

