def mul(a,b,M):
    c=[0]*M
    for i,x in enumerate(a):
        if x:
            for j,y in enumerate(b):
                c[(i+j)%M]=(c[(i+j)%M]+x*y)%MOD
    return c

def power(a,e,M):
    r=[0]*M;r[0]=1
    while e:
        if e&1:r=mul(r,a,M)
        a=mul(a,a,M);e//=2
    return r

def bm(s):
    C=[1];B=[1];L=0;m=1;b=1
    for n in range(len(s)):
        d=s[n]
        for i in range(1,L+1):d=(d+C[i]*s[n-i])%MOD
        if d==0:m+=1;continue
        T=C[:];coef=d*pow(b,MOD-2,MOD)%MOD
        if len(C)<len(B)+m:C += [0]*(len(B)+m-len(C))
        for j in range(len(B)):C[j+m]=(C[j+m]-coef*B[j])%MOD
        if 2*L<=n:
            L=n+1-L;B=T;b=d;m=1
        else:m+=1
    return [(-x)%MOD for x in C[1:L+1]]

def lin_nth(init,rec,n):
    L=len(rec)
    if n<len(init):return init[n]
    def combine(a,b):
        t=[0]*(2*L-1)
        for i,x in enumerate(a):
            if x:
                for j,y in enumerate(b):t[i+j]=(t[i+j]+x*y)%MOD
        for i in range(2*L-2,L-1,-1):
            if t[i]:
                for j in range(1,L+1):t[i-j]=(t[i-j]+t[i]*rec[j-1])%MOD
        return t[:L]
    pol=[1]+[0]*(L-1);x=[0]*L
    if L==1:x[0]=rec[0]
    else:x[1]=1
    while n:
        if n&1:pol=combine(pol,x)
        x=combine(x,x);n//=2
    return sum(pol[i]*init[i] for i in range(L))%MOD

