from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        # Each pair is oriented as (a, b), a < b. It begins restricting
        # subarrays ending at position b: their left endpoint must be > a.
        events = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            events[b].append((a, i))

        largest = second_largest = 0
        largest_id = -1
        gains = [0] * m
        total = 0

        for right in range(1, n + 1):
            for a, idx in events[right]:
                if a > largest:
                    second_largest = largest
                    largest = a
                    largest_id = idx
                elif a > second_largest:
                    # This also handles a tie with largest: then removal of
                    # just one of the tied pairs cannot lower the maximum.
                    second_largest = a

            # With all pairs present, valid left endpoints are
            # largest + 1, ..., right.
            total += right - largest

            # Removing the unique pair supplying largest relaxes this
            # right endpoint's bound to second_largest.
            if largest_id != -1 and largest > second_largest:
                gains[largest_id] += largest - second_largest

        return total + max(gains)

