import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        edges[i] = (a-1, b-1, c)

    queries = []
    closed = [False] * M
    for _ in range(Q):
        z = list(map(int, input().split()))
        if z[0] == 1:
            i = z[1]-1
            closed[i] = True
            queries.append((1, i))
        else:
            queries.append((2, z[1]-1, z[2]-1))

    INF = 10**30
    d = [[INF] * N for _ in range(N)]
    for i in range(N):
        d[i][i] = 0
    for i, (u, v, w) in enumerate(edges):
        if not closed[i]:
            d[u][v] = d[v][u] = w

    # All-pairs shortest paths after every road that is ever closed is removed.
    for k in range(N):
        dk = d[k]
        for i in range(N):
            dik = d[i][k]
            if dik == INF:
                continue
            di = d[i]
            for j in range(N):
                x = dik + dk[j]
                if x < di[j]:
                    di[j] = x

    answers = []
    for q in reversed(queries):
        if q[0] == 2:
            x, y = q[1], q[2]
            val = d[x][y]
            answers.append(-1 if val == INF else val)
        else:
            u, v, w = edges[q[1]]
            # An inserted edge can occur at most once in a shortest path.
            # Snapshot the old distance vectors before updating the matrix.
            du = [d[i][u] for i in range(N)]
            dv = [d[i][v] for i in range(N)]
            rowu = d[u][:]
            rowv = d[v][:]
            for i in range(N):
                row = d[i]
                a = du[i] + w
                b = dv[i] + w
                for j in range(N):
                    old = row[j]
                    x = a + rowv[j]
                    if x < old:
                        old = x
                    x = b + rowu[j]
                    if x < old:
                        row[j] = old = x
                    else:
                        row[j] = old

    print('\n'.join(map(str, reversed(answers))))

if __name__ == '__main__':
    main()

