class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (x + 1)
        dp[0] = 1

        for i in range(1, n + 1):
            ndp = [0] * (x + 1)
            for k in range(1, min(i, x) + 1):
                # Add the new performer to one of k existing stages, or
                # start a new scored band at one of x-k+1 unused stages.
                ndp[k] = (
                    k * dp[k] + (x - k + 1) * y * dp[k - 1]
                ) % MOD
            dp = ndp

        return sum(dp) % MOD

