import sys
from collections import deque

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    n = int(data[0])
    graph = [row.decode() for row in data[1:1 + n]]

    incoming = [[[] for _ in range(26)] for _ in range(n)]
    outgoing = [[[] for _ in range(26)] for _ in range(n)]
    dist = [[-1] * n for _ in range(n)]
    q = deque()

    # The center of a palindrome is either empty or one edge.
    for i in range(n):
        dist[i][i] = 0
        q.append(i * n + i)
    for i in range(n):
        for j, ch in enumerate(graph[i]):
            if ch != '-':
                c = ord(ch) - ord('a')
                outgoing[i][c].append(j)
                incoming[j][c].append(i)
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    q.append(i * n + j)

    # Add matching outer edges to an already-known palindromic path.
    while q:
        u, v = divmod(q.popleft(), n)
        new_dist = dist[u][v] + 2
        for c in range(26):
            for x in incoming[u][c]:
                row = dist[x]
                for y in outgoing[v][c]:
                    if row[y] == -1:
                        row[y] = new_dist
                        q.append(x * n + y)

    sys.stdout.write('\n'.join(' '.join(map(str, row)) for row in dist))

if __name__ == '__main__':
    solve()

