def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    u = []
    d = []
    p = 2
    for _ in range(n):
        u.append(data[p])
        d.append(data[p + 1])
        p += 2

    def feasible(h):
        lo = max(0, h - d[0])
        hi = min(u[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            lo = max(max(0, h - d[i]), lo - x)
            hi = min(min(u[i], h), hi + x)
            if lo > hi:
                return False
        return True

    left = 0
    right = min(u[i] + d[i] for i in range(n)) + 1
    while right - left > 1:
        mid = (left + right) // 2
        if feasible(mid):
            left = mid
        else:
            right = mid

    total = sum(u[i] + d[i] for i in range(n))
    print(total - n * left)

