import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:1+n]

    # For each t, a crease is a mountain exactly when
    # i + A == 2^t (mod 2^(t+2)).
    weights = {}
    for x in a:
        for t in range(98):
            d = t + 2
            r = ( (1 << t) - x) % (1 << d)
            key = (d, r)
            weights[key] = weights.get(key, 0) + 1

    # Maximum sum of weights on a single low-bit-first trie path.
    # Prefixes are residues modulo 2^d.
    best = 0
    for (d, r), w in weights.items():
        score = 0
        for level in range(1, d + 1):
            score += weights.get((level, r % (1 << level)), 0)
        if score > best:
            best = score

    # At t >= 98, within 1 <= i+A <= 2^100-1, the only possible
    # mountain crease is exactly 2^t. Check these exceptional i directly.
    limit = (1 << 100) - a[-1] - 1
    candidates = set()
    for x in a:
        for t in range(98, 100):
            i = (1 << t) - x
            if 1 <= i <= limit:
                candidates.add(i)
    for i in candidates:
        score = 0
        for x in a:
            y = i + x
            # mountain iff y modulo 4*lowbit(y) is lowbit(y)
            low = y & -y
            if ((y // low) & 3) == 1:
                score += 1
        best = max(best, score)

    print(best)

if __name__ == '__main__':
    main()

