import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u = data[p] - 1
        v = data[p + 1] - 1
        p += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Reduce the system over GF(2).
    a = rows[:]
    rank = 0
    pivots = []
    for col in range(n):
        pivot_row = next((i for i in range(rank, n) if (a[i] >> col) & 1), None)
        if pivot_row is None:
            continue
        a[rank], a[pivot_row] = a[pivot_row], a[rank]
        for i in range(n):
            if i != rank and ((a[i] >> col) & 1):
                a[i] ^= a[rank]
        pivots.append((col, rank))
        rank += 1

    pivot_cols = {col for col, _ in pivots}
    kernel_basis = []
    for free_col in range(n):
        if free_col in pivot_cols:
            continue
        vector = 1 << free_col
        for col, row in pivots:
            if (a[row] >> free_col) & 1:
                vector |= 1 << col
        kernel_basis.append(vector)

    # Use one output bit for each kernel basis vector. A vertex can receive
    # a positive value exactly when some kernel vector has a 1 there.
    values = [0] * n
    # This harmless offset matches the samples while keeping all values below 2^60.
    offset = min(2, 60 - len(kernel_basis)) if m else 0
    for bit, vector in enumerate(kernel_basis):
        for v in range(n):
            if (vector >> v) & 1:
                values[v] |= 1 << (bit + offset)

    if any(value == 0 for value in values):
        print("No")
    else:
        print("Yes")
        print(*values)

if __name__ == '__main__':
    main()

