import math

N = int(sys.stdin.readline())

# Find floor(cuberoot(N)) using integer arithmetic.
lo, hi = 0, 1
while hi ** 3 <= N:
    hi *= 2
while lo + 1 < hi:
    mid = (lo + hi) // 2
    if mid ** 3 <= N:
        lo = mid
    else:
        hi = mid

# Let d = x-y. Then N/d = 3y^2 + 3dy + d^2.
# With z = 2y+d, this becomes z^2 = (4N/d - d^2)/3.
for d in range(1, lo + 1):
    if N % d != 0:
        continue
    q = N // d
    value = 4 * q - d * d
    if value <= 0 or value % 3 != 0:
        continue
    z2 = value // 3
    z = math.isqrt(z2)
    if z * z != z2 or (z - d) % 2 != 0:
        continue
    y = (z - d) // 2
    if y > 0:
        print(y + d, y)
        break
else:
    print(-1)

