from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        def completions(rem_odd, rem_even, previous_parity, left):
            need_odd = need_even = 0
            parity = 1 - previous_parity
            for _ in range(left):
                if parity == 1:
                    need_odd += 1
                else:
                    need_even += 1
                parity = 1 - parity
            if need_odd != rem_odd or need_even != rem_even:
                return 0
            return fact[rem_odd] * fact[rem_even]

        total = 0
        for p, cnt in ((1, odds), (0, evens)):
            if cnt:
                total += cnt * completions(
                    odds - (p == 1), evens - (p == 0), p, n - 1
                )
        if k > total:
            return []

        remaining = list(range(1, n + 1))
        result = []
        prev = None
        while remaining:
            chosen = None
            odd_count = sum(y & 1 for y in remaining)
            for x in remaining:
                p = x & 1
                if prev is not None and p == prev:
                    continue
                rem_odd = odd_count - (p == 1)
                rem_even = len(remaining) - odd_count - (p == 0)
                ways = completions(rem_odd, rem_even, p, len(remaining) - 1)
                if k > ways:
                    k -= ways
                else:
                    chosen = x
                    break
            if chosen is None:
                return []
            result.append(chosen)
            remaining.remove(chosen)
            prev = chosen & 1
        return result

