class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2
        powers = [1] * n
        for i in range(1, n):
            powers[i] = (powers[i - 1] * 10) % k

        coeff = []
        for i in range(half):
            j = n - 1 - i
            c = powers[i]
            if i != j:
                c = (c + powers[j]) % k
            coeff.append(c)

        # dp[i][r]: digits i onward can contribute remainder r modulo k.
        dp = [[False] * k for _ in range(half + 1)]
        dp[half][0] = True
        for i in range(half - 1, -1, -1):
            lo = 1 if i == 0 else 0
            c = coeff[i]
            row, nxt = dp[i], dp[i + 1]
            for d in range(lo, 10):
                add = d * c % k
                for r in range(k):
                    if nxt[r]:
                        row[(add + r) % k] = True

        # Greedily maximize each left-half digit while retaining feasibility.
        chosen = []
        rem = 0
        for i in range(half):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (rem + d * coeff[i]) % k
                if dp[i + 1][(-nr) % k]:
                    chosen.append(str(d))
                    rem = nr
                    break

        left = ''.join(chosen)
        if n % 2:
            return left + left[-2::-1]
        return left + left[::-1]

