from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        size = 4 * n
        sm = [0] * size
        mx = [-1] * size
        lazy = [None] * size

        def apply(p, l, r, v):
            sm[p] = (r - l + 1) * v
            mx[p] = v
            lazy[p] = v

        def push(p, l, r):
            v = lazy[p]
            if v is not None and l < r:
                m = (l + r) // 2
                apply(p * 2, l, m, v)
                apply(p * 2 + 1, m + 1, r, v)
            lazy[p] = None

        def assign(p, l, r, ql, qr, v):
            if ql > r or qr < l or ql > qr:
                return
            if ql <= l and r <= qr:
                apply(p, l, r, v)
                return
            push(p, l, r)
            m = (l + r) // 2
            assign(p * 2, l, m, ql, qr, v)
            assign(p * 2 + 1, m + 1, r, ql, qr, v)
            sm[p] = sm[p * 2] + sm[p * 2 + 1]
            mx[p] = max(mx[p * 2], mx[p * 2 + 1])

        def point(p, l, r, i, v):
            if l == r:
                apply(p, l, r, v)
                return
            push(p, l, r)
            m = (l + r) // 2
            if i <= m:
                point(p * 2, l, m, i, v)
            else:
                point(p * 2 + 1, m + 1, r, i, v)
            sm[p] = sm[p * 2] + sm[p * 2 + 1]
            mx[p] = max(mx[p * 2], mx[p * 2 + 1])

        def query(p, l, r, ql, qr):
            if ql <= l and r <= qr:
                return sm[p]
            push(p, l, r)
            m = (l + r) // 2
            result = 0
            if ql <= m:
                result += query(p * 2, l, m, ql, qr)
            if qr > m:
                result += query(p * 2 + 1, m + 1, r, ql, qr)
            return result

        def first_at_least(p, l, r, ql, qr, value):
            if r < ql or l > qr or mx[p] < value:
                return qr + 1
            if l == r:
                return l
            push(p, l, r)
            m = (l + r) // 2
            result = first_at_least(p * 2, l, m, ql, qr, value)
            if result <= qr:
                return result
            return first_at_least(p * 2 + 1, m + 1, r, ql, qr, value)

        prefix = [0]
        for value in nums:
            prefix.append(prefix[-1] + value)

        right = n - 1
        answer = 0
        for left in range(n - 1, -1, -1):
            value = nums[left]
            point(1, 0, n - 1, left, value)
            if left < right:
                pos = first_at_least(1, 0, n - 1, left + 1, right, value)
                assign(1, 0, n - 1, left + 1, pos - 1, value)

            while left < right and query(1, 0, n - 1, left, right) - (prefix[right + 1] - prefix[left]) > k:
                right -= 1
            answer += right - left + 1

        return answer

