from functools import cmp_to_key
import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, K = data[:2]
    fs = list(zip(data[2::2], data[3::2]))

    def cmp(x, y):
        a, b = x
        c, d = y
        if a == 1 or c == 1:
            if a == 1 and c != 1:
                return -1
            if c == 1 and a != 1:
                return 1
            return 0
        # Sort by decreasing B / (A - 1), using exact cross-products.
        left = b * (c - 1)
        right = d * (a - 1)
        if left > right:
            return -1
        if left < right:
            return 1
        return 0

    fs.sort(key=cmp_to_key(cmp))

    # dp[k] is the maximum value after choosing k functions processed so far.
    dp = [None] * (K + 1)
    dp[0] = 1
    seen = 0
    for a, b in fs:
        for k in range(min(K, seen + 1), 0, -1):
            if dp[k - 1] is not None:
                value = a * dp[k - 1] + b
                if dp[k] is None or value > dp[k]:
                    dp[k] = value
        seen += 1

    print(dp[K])

main()

