class Solution:
    def makeStringGood(self, s: str) -> int:
        from collections import Counter

        counts = Counter(s)
        if len(counts) == 1:
            return 0

        # For a chosen final frequency k, process letters from left to right.
        # A carry is the number of characters changed from the previous letter.
        # Carries larger than k are unnecessary: the next letter can use at most
        # k of them, and the remainder can be deleted instead.
        answer = len(s)
        max_count = max(counts.values())

        for k in range(1, max_count + 1):
            dp = [0] + [answer] * k
            for letter in range(26):
                c = counts.get(chr(ord('a') + letter), 0)
                ndp = [answer] * (k + 1)

                for carry, cost in enumerate(dp):
                    if cost >= answer:
                        continue

                    total = c + carry
                    for final_count in (0, k):
                        if total < final_count:
                            # Inserting characters cannot create a carry.
                            ndp[0] = min(ndp[0], cost + final_count - total)
                        else:
                            # Each surplus character can be deleted or changed
                            # to the next letter, at one operation either way.
                            base_cost = cost + total - final_count
                            limit = min(k, total - final_count)
                            for outgoing in range(limit + 1):
                                ndp[outgoing] = min(ndp[outgoing], base_cost)

                dp = ndp

            answer = min(answer, dp[0])

        return answer

