from bisect import bisect_left, bisect_right

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first = p.find('*')
        second = p.find('*', first + 1)
        a = p[:first]
        b = p[first + 1:second]
        c = p[second + 1:]
        n = len(s)

        def occurrences(t):
            m = len(t)
            if m == 0:
                return list(range(n + 1))

            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = prefix[j - 1]
                if t[i] == t[j]:
                    j += 1
                    prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = prefix[j - 1]
                if ch == t[j]:
                    j += 1
                    if j == m:
                        result.append(i - m + 1)
                        j = prefix[j - 1]
            return result

        starts_a = occurrences(a)
        starts_b = occurrences(b)
        starts_c = occurrences(c)

        answer = n + 1
        for start_b in starts_b:
            # Latest A ending no later than B's start.
            i = bisect_right(starts_a, start_b - len(a)) - 1
            # Earliest C starting no earlier than B's end.
            k = bisect_left(starts_c, start_b + len(b))
            if i >= 0 and k < len(starts_c):
                answer = min(answer, starts_c[k] + len(c) - starts_a[i])

        return -1 if answer == n + 1 else answer

