import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    adj = [[] for _ in range(n)]
    p = 2
    for _ in range(m):
        x, y, z = data[p] - 1, data[p + 1] - 1, data[p + 2]
        p += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    # potential[u] is the XOR difference from the component's root.
    potential = [-1] * n
    answer = [0] * n
    for start in range(n):
        if potential[start] != -1:
            continue
        potential[start] = 0
        stack = [start]
        component = []
        while stack:
            u = stack.pop()
            component.append(u)
            for v, z in adj[u]:
                expected = potential[u] ^ z
                if potential[v] == -1:
                    potential[v] = expected
                    stack.append(v)
                elif potential[v] != expected:
                    print(-1)
                    return

        for u in component:
            answer[u] = potential[u]
        # Choose each bit of the component root independently to minimize
        # the number of resulting 1 bits in this component.
        for bit in range(31):
            ones = sum((potential[u] >> bit) & 1 for u in component)
            if ones > len(component) - ones:
                mask = 1 << bit
                for u in component:
                    answer[u] ^= mask

    print(*answer)

