    a = data[2:]

    r = min(k, n - k)
    total_xor = 0
    for x in a:
        total_xor ^= x

    best = 0
    if k <= n - k:
        for chosen in combinations(a, r):
            value = 0
            for x in chosen:
                value ^= x
            best = max(best, value)
    else:
        # XOR of the chosen elements equals total_xor XOR omitted elements.
        for omitted in combinations(a, r):
            value = total_xor
            for x in omitted:
                value ^= x
            best = max(best, value)

    print(best)

