class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Construct the ordered postorder string iteratively.
        post = []
        stack = [(0, False)]
        while stack:
            v, done = stack.pop()
            if done:
                post.append(s[v])
            else:
                stack.append((v, True))
                for c in reversed(children[v]):
                    stack.append((c, False))
        t = ''.join(post)

        # Manacher's odd-length palindrome radii.
        d1 = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 1 if i > r else min(d1[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < n and t[i - k] == t[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1

        # Manacher's even-length radii; d2[i] is centered between i-1 and i.
        d2 = [0] * n
        l, r = 0, -1
        for i in range(n):
            k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < n and t[i - k - 1] == t[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1

        # Subtree intervals in the postorder string, inclusive.
        left = [0] * n
        right = [0] * n
        stack = [(0, False)]
        pos = 0
        while stack:
            v, exiting = stack.pop()
            if exiting:
                right[v] = pos
                pos += 1
            else:
                left[v] = pos
                stack.append((v, True))
                for c in reversed(children[v]):
                    stack.append((c, False))

        answer = []
        for v in range(n):
            a, b = left[v], right[v]
            length = b - a + 1
            if length & 1:
                center = (a + b) // 2
                answer.append(d1[center] >= length // 2 + 1)
            else:
                center = (a + b + 1) // 2
                answer.append(d2[center] >= length // 2)
        return answer

