class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        mins = [None] * k
        mins[0] = 0
        prefix = 0
        answer = None
        for j, x in enumerate(nums, 1):
            prefix += x
            r = j % k
            if mins[r] is not None:
                candidate = prefix - mins[r]
                if answer is None or candidate > answer:
                    answer = candidate
            if mins[r] is None or prefix < mins[r]:
                mins[r] = prefix
        return answer

