class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        total = sum(nums)
        freq = {}
        for value in nums:
            freq[value] = freq.get(value, 0) + 1

        # If x is the outlier and s is the sum of the special numbers,
        # then total = x + s + s, so s = (total - x) / 2.
        for outlier in sorted(freq, reverse=True):
            remaining = total - outlier
            if remaining % 2:
                continue
            special_sum = remaining // 2
            needed = 1 + (special_sum == outlier)
            if freq.get(special_sum, 0) >= needed:
                return outlier

        # The input guarantees that a potential outlier exists.
        raise ValueError("No valid outlier")

