class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        def is_prime(x):
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            d = 3
            while d * d <= x:
                if x % d == 0:
                    return False
                d += 2
            return True

        if is_prime(n) or is_prime(m):
            return -1

        length = len(str(n))
        low = 0 if length == 1 else 10 ** (length - 1)
        dist = {n: n}  # Include the starting integer in the total cost.
        heap = [(n, n)]

        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            place = 1
            for pos in range(length):
                digit = (x // place) % 10
                if digit < 9:
                    y = x + place
                    if not is_prime(y):
                        new_cost = cost + y
                        if new_cost < dist.get(y, float('inf')):
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))

                # Do not let a multi-digit number acquire a leading zero.
                if digit > 0 and not (pos == length - 1 and digit == 1 and length > 1):
                    y = x - place
                    if y >= low and not is_prime(y):
                        new_cost = cost + y
                        if new_cost < dist.get(y, float('inf')):
                            dist[y] = new_cost
                            heapq.heappush(heap, (new_cost, y))
                place *= 10

        return -1

