class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        prefix_ok = [False] * n
        ans = 0

        # Count splits where nums1 is a prefix of nums2.
        for i in range(1, n):
            if 2 * i <= n:
                prefix_ok[i] = nums[:i] == nums[i:2 * i]
                if prefix_ok[i]:
                    ans += n - 2 * i

        # Count splits where nums2 is a prefix of nums3. For each length d
        # of nums2, scan matching positions and maintain their common run.
        for d in range(1, n):
            max_i = n - 2 * d
            if max_i < 1:
                continue

            run = 0
            for i in range(n - d - 1, -1, -1):
                if nums[i] == nums[i + d]:
                    run += 1
                else:
                    run = 0

                if 1 <= i <= max_i and run >= d:
                    ans += 1
                    # This split was counted in both groups.
                    if d >= i and prefix_ok[i]:
                        ans -= 1

