class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)

        is_target = bytearray(n)
        for i in targetIndices:
            is_target[i] = 1

        inf = n + 1
        # dp[j] is the minimum number of target indices used by an
        # embedding of pattern[:j] in the source prefix processed so far.
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = is_target[i]
            # Descending order ensures source[i] is used at most once.
            for j in range(m, 0, -1):
                if ch == pattern[j - 1]:
                    candidate = dp[j - 1] + cost
                    if candidate < dp[j]:
                        dp[j] = candidate

        # Every target index not used in this minimum-cost embedding can be removed.
        return len(targetIndices) - dp[m]

