class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set("aeiou")
        n = len(word)
        total = 0

        for left in range(n):
            vowel_counts = {v: 0 for v in vowels}
            consonants = 0

            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    vowel_counts[ch] += 1
                else:
                    consonants += 1
                    if consonants > k:
                        break

                if consonants == k and all(vowel_counts[v] > 0 for v in vowels):
                    total += 1

        return total

